#!/usr/bin/env python3
# GENERATED by plugin-cursor/scripts/compose.sh — edit plugin/ then re-compose
"""
Accessibility Checker — WCAG compliance checks on HTML/JSX/TSX files.

Usage:
    python3 accessibility_checker.py <directory>
    python3 accessibility_checker.py frontend/app/
    python3 accessibility_checker.py --help

Checks:
- Missing skip-to-content links
- Missing lang attribute on <html>
- Missing <main> landmark
- Color contrast heuristics
- Missing form labels and ARIA attributes
- Missing alt text
- Keyboard accessibility patterns
- Focus management issues

Stdlib-only — no external dependencies.
"""

import argparse
import json
import os
import re
import sys
from typing import List, Dict, Tuple

CRITICAL = "Critical"
HIGH = "High"
MEDIUM = "Medium"
LOW = "Low"

SKIP_DIRS = {'node_modules', '.next', 'dist', 'build', '.git'}


class Finding:
    def __init__(self, severity: str, wcag: str, message: str,
                 file: str, line: int = 0, suggestion: str = ""):
        self.severity = severity
        self.wcag = wcag  # WCAG criterion
        self.message = message
        self.file = file
        self.line = line
        self.suggestion = suggestion

    def to_dict(self) -> dict:
        return {
            "severity": self.severity,
            "wcag": self.wcag,
            "message": self.message,
            "file": self.file,
            "line": self.line,
            "suggestion": self.suggestion,
        }


def find_files(directory: str) -> List[str]:
    """Find frontend source files."""
    files = []
    extensions = ('.tsx', '.jsx', '.vue', '.svelte', '.html', '.astro')
    for root, dirs, filenames in os.walk(directory):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        for f in filenames:
            if f.endswith(extensions):
                files.append(os.path.join(root, f))
    return files


def check_landmark_structure(files: List[str]) -> List[Finding]:
    """Check for proper landmark elements across the app."""
    findings = []
    has_main = False
    has_nav = False
    has_skip_link = False

    for filepath in files:
        try:
            with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
        except (IOError, OSError):
            continue

        if re.search(r'<main\b|role\s*=\s*["\']main["\']', content):
            has_main = True
        if re.search(r'<nav\b|role\s*=\s*["\']navigation["\']', content):
            has_nav = True
        if re.search(r'skip.*(?:content|main|nav)', content, re.IGNORECASE):
            has_skip_link = True

    if not has_main:
        findings.append(Finding(
            HIGH, "WCAG 1.3.1",
            "No <main> landmark found in the application",
            "app-wide", 0,
            "Add a <main> element to wrap the primary content area"
        ))
    if not has_skip_link:
        findings.append(Finding(
            MEDIUM, "WCAG 2.4.1",
            "No skip-to-content link found",
            "app-wide", 0,
            "Add a skip-to-content link as the first focusable element in the layout"
        ))

    return findings


def check_file(content: str, filepath: str) -> List[Finding]:
    """Run all per-file accessibility checks."""
    findings = []
    lines = content.split('\n')

    for i, line in enumerate(lines, 1):
        # Missing alt text (WCAG 1.1.1)
        if re.search(r'<img\b', line, re.IGNORECASE):
            if not re.search(r'\balt\s*=', line, re.IGNORECASE):
                context = '\n'.join(lines[max(0, i-1):min(i+3, len(lines))])
                if not re.search(r'\balt\s*=', context, re.IGNORECASE):
                    findings.append(Finding(
                        CRITICAL, "WCAG 1.1.1",
                        "Image missing alt attribute",
                        filepath, i,
                        'Add alt="descriptive text" or alt="" for decorative images'
                    ))

        # Missing form labels (WCAG 1.3.1)
        if re.search(r'<(input|select|textarea)\b', line, re.IGNORECASE):
            if re.search(r'type\s*=\s*["\'](?:hidden|submit|button)["\']', line, re.IGNORECASE):
                continue
            context = '\n'.join(lines[max(0, i-5):min(i+3, len(lines))])
            has_label = (
                re.search(r'aria-label\s*=', context, re.IGNORECASE) or
                re.search(r'aria-labelledby\s*=', context, re.IGNORECASE) or
                re.search(r'<label\b', context, re.IGNORECASE) or
                re.search(r'<Label\b', context) or
                re.search(r'placeholder\s*=', context, re.IGNORECASE)
            )
            if not has_label:
                findings.append(Finding(
                    HIGH, "WCAG 1.3.1",
                    "Form input without label or aria-label",
                    filepath, i,
                    "Add a visible <label> or aria-label attribute"
                ))

        # Icon-only buttons without labels (WCAG 1.1.1)
        if re.search(r'<button\b|<Button\b', line):
            context = '\n'.join(lines[max(0, i-1):min(i+3, len(lines))])
            has_icon = re.search(r'(?:Icon|icon|svg|<i\b)', context)
            has_text_or_label = (
                re.search(r'aria-label\s*=', context) or
                re.search(r'title\s*=', context) or
                re.search(r'>[^<{]+<', context)  # Text content between tags
            )
            if has_icon and not has_text_or_label:
                findings.append(Finding(
                    HIGH, "WCAG 1.1.1",
                    "Icon button without accessible label",
                    filepath, i,
                    "Add aria-label to icon-only buttons"
                ))

        # Autofocus (WCAG 3.2.1) — warning only
        if re.search(r'\bautofocus\b|autoFocus\b', line):
            findings.append(Finding(
                LOW, "WCAG 3.2.1",
                "autoFocus may cause unexpected focus changes",
                filepath, i,
                "Use autoFocus sparingly — only on the primary input of a page"
            ))

        # tabIndex > 0 (WCAG 2.4.3)
        if re.search(r'tabIndex\s*=\s*[{"\']?\s*[1-9]', line) or re.search(r'tabindex\s*=\s*["\']?[1-9]', line):
            findings.append(Finding(
                MEDIUM, "WCAG 2.4.3",
                "Positive tabIndex disrupts natural tab order",
                filepath, i,
                "Use tabIndex={0} or tabIndex={-1} only. Never use positive tabIndex."
            ))

        # onClick on non-interactive elements without keyboard support
        if re.search(r'<(?:div|span|p|li)\b.*onClick', line):
            context = '\n'.join(lines[max(0, i-1):min(i+3, len(lines))])
            has_keyboard = (
                re.search(r'onKeyDown|onKeyUp|onKeyPress|role\s*=\s*["\']button', context) or
                re.search(r'tabIndex|tabindex', context)
            )
            if not has_keyboard:
                findings.append(Finding(
                    HIGH, "WCAG 2.1.1",
                    "Click handler on non-interactive element without keyboard support",
                    filepath, i,
                    "Use <button> instead, or add role=\"button\" + tabIndex={0} + onKeyDown handler"
                ))

        # Removed focus outline
        if re.search(r'outline\s*:\s*(?:0|none)', line, re.IGNORECASE):
            context = '\n'.join(lines[max(0, i-3):min(i+3, len(lines))])
            has_replacement = re.search(r'box-shadow|ring|focus-visible', context)
            if not has_replacement:
                findings.append(Finding(
                    CRITICAL, "WCAG 2.4.7",
                    "Focus indicator removed without replacement",
                    filepath, i,
                    "Always provide a visible focus indicator"
                ))

    # Check for heading hierarchy
    headings = []
    for i, line in enumerate(lines, 1):
        m = re.search(r'<[hH]([1-6])\b', line)
        if m:
            headings.append((i, int(m.group(1))))

    for j in range(1, len(headings)):
        prev_level = headings[j-1][1]
        curr_level = headings[j][1]
        if curr_level > prev_level + 1:
            findings.append(Finding(
                MEDIUM, "WCAG 1.3.1",
                f"Heading level skipped: h{prev_level} → h{curr_level}",
                filepath, headings[j][0],
                f"Use h{prev_level + 1} instead of h{curr_level}"
            ))

    return findings


def run_checks(directory: str) -> Tuple[List[Finding], dict]:
    """Run all accessibility checks."""
    files = find_files(directory)
    if not files:
        print(f"No frontend files found in {directory}", file=sys.stderr)
        sys.exit(1)

    all_findings: List[Finding] = []

    # App-wide checks
    all_findings.extend(check_landmark_structure(files))

    # Per-file checks
    for filepath in files:
        try:
            with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
        except (IOError, OSError):
            continue
        all_findings.extend(check_file(content, filepath))

    summary = {
        "files_scanned": len(files),
        "total_findings": len(all_findings),
        "by_severity": {},
        "by_wcag": {},
    }

    for sev in [CRITICAL, HIGH, MEDIUM, LOW]:
        count = sum(1 for f in all_findings if f.severity == sev)
        if count:
            summary["by_severity"][sev] = count

    for f in all_findings:
        summary["by_wcag"][f.wcag] = summary["by_wcag"].get(f.wcag, 0) + 1

    return all_findings, summary


def main():
    parser = argparse.ArgumentParser(
        description="Accessibility Checker — WCAG compliance checks on frontend code"
    )
    parser.add_argument("directory", help="Directory to check")
    parser.add_argument("--format", choices=["text", "json"], default="text",
                       help="Output format")
    parser.add_argument("--min-severity", choices=["critical", "high", "medium", "low"],
                       default="low", help="Minimum severity")

    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        print(f"Error: {args.directory} is not a directory", file=sys.stderr)
        sys.exit(1)

    findings, summary = run_checks(args.directory)

    severity_filter = {
        "critical": [CRITICAL],
        "high": [CRITICAL, HIGH],
        "medium": [CRITICAL, HIGH, MEDIUM],
        "low": [CRITICAL, HIGH, MEDIUM, LOW],
    }
    allowed = severity_filter[args.min_severity]
    findings = [f for f in findings if f.severity in allowed]

    if args.format == "json":
        print(json.dumps({
            "summary": summary,
            "findings": [f.to_dict() for f in findings],
        }, indent=2))
    else:
        print("━" * 60)
        print("  ACCESSIBILITY AUDIT (WCAG 2.1 AA)")
        print("━" * 60)
        print(f"\n  Files scanned: {summary['files_scanned']}")
        print(f"  Total findings: {summary['total_findings']}\n")

        if summary["by_severity"]:
            for sev, count in summary["by_severity"].items():
                print(f"  {sev}: {count}")

        if summary["by_wcag"]:
            print("\n  By WCAG Criterion:")
            for wcag, count in sorted(summary["by_wcag"].items()):
                print(f"    {wcag}: {count}")

        severity_order = {CRITICAL: 0, HIGH: 1, MEDIUM: 2, LOW: 3}
        sorted_findings = sorted(findings, key=lambda f: severity_order.get(f.severity, 4))

        current_severity = None
        for f in sorted_findings:
            if f.severity != current_severity:
                current_severity = f.severity
                print(f"\n  [{current_severity}]")
                print("  " + "─" * 40)
            loc = f"{f.file}:{f.line}" if f.line else f.file
            print(f"\n  [{f.wcag}] {f.message}")
            print(f"  Location: {loc}")
            if f.suggestion:
                print(f"  Fix: {f.suggestion}")

        print("\n" + "━" * 60)

    sys.exit(1 if summary["by_severity"].get(CRITICAL, 0) > 0 else 0)


if __name__ == "__main__":
    main()
